/**
 * Manual penetration-test runbook for Omanda AI's public site (omanda-ai.com).
 *
 * A methodology + checklist for an authorised human tester to execute from a
 * proper testing environment (Burp/ZAP + CLI tooling). It contains payloads and
 * techniques the way the OWASP Web Security Testing Guide does — this is a
 * defensive engagement deliverable, not an attack script.
 *
 * CORRECTION NOTICE (2026-09-14): this file was scaffolded from
 * showcase-esaalnybot's runbook, which was written against a confirmed
 * Vite/React SPA + separate JSON API host + multi-tenant chat-widget embed
 * (data-chatbot-id). None of that has been confirmed for omanda-ai.com.
 *
 * What IS confirmed for omanda-ai.com, from the real passive crawl
 * (data/crawl.json, 8 same-origin pages: /, /pricing, /contact, /help,
 * /data-deletion, /privacy, /terms, /refund-policy):
 *   - It is a server-rendered HTML marketing/legal-pages site (Arabic RTL,
 *     English toggle via localStorage), fronted by Cloudflare (Server:
 *     cloudflare, not nginx). No JSON API root, no widget.js, no
 *     data-chatbot-id embed, no login/register/reset page was found linked
 *     from any of the 8 crawled pages.
 *   - Real response headers ARE present: HSTS, X-Content-Type-Options,
 *     X-Frame-Options, Referrer-Policy, Permissions-Policy. Only CSP is
 *     missing — the opposite of "no security headers at all."
 *   - No cookie-flag violations were measured on any page.
 *
 * Cases below tagged target: 'app' generally still apply (they test the
 * public site actually found). Cases tagged target: 'api' or 'widget'
 * describe a JSON-API / multi-tenant-widget surface that was NOT discovered
 * on this site — they are kept as inherited OWASP-style methodology in case
 * a tester later finds an actual product/app host (e.g. a separate
 * authenticated subdomain not linked from these public pages), but every
 * such case must be re-verified against a confirmed target before
 * execution, not assumed to apply. Do not treat any 'api'/'widget' case's
 * embedded assumptions (the JSON banner, the chatbot-id parameter, the
 * app/api host split) as fact for this target.
 *
 * Consumed by src/build-runbook.ts -> data/pentest-runbook.json + PENTEST-RUNBOOK.md
 * and rendered as the "Pentest plan" tab of the showcase dashboard.
 */

export type Sev = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'INFO';
export type Target = 'app' | 'api' | 'widget' | 'infra' | 'all';

export interface TestCase {
  id: string;
  title: string;
  target: Target;
  category: string;
  refs: string[]; // WSTG / OWASP API / CWE ids
  severityIfFound: Sev;
  objective: string;
  steps: string[];
  payloads?: string[];
  tools: string[];
  evidence: string;
  secureLooksLike: string;
  remediation: string;
}

export interface Phase {
  id: string;
  name: string;
  goal: string;
  cases: TestCase[];
}

export interface Runbook {
  meta: {
    title: string;
    version: string;
    generated: string;
    authoredBy: string;
    targets: { key: string; url: string; notes: string }[];
    knownFacts: string[];
  };
  authorization: string[];
  rulesOfEngagement: string[];
  prerequisites: string[];
  toolchain: { name: string; purpose: string; config: string }[];
  phases: Phase[];
  reporting: { field: string; note: string }[];
}

const T = (
  id: string,
  title: string,
  target: Target,
  category: string,
  refs: string[],
  severityIfFound: Sev,
  objective: string,
  steps: string[],
  tools: string[],
  evidence: string,
  secureLooksLike: string,
  remediation: string,
  payloads?: string[],
): TestCase => ({
  id,
  title,
  target,
  category,
  refs,
  severityIfFound,
  objective,
  steps,
  ...(payloads ? { payloads } : {}),
  tools,
  evidence,
  secureLooksLike,
  remediation,
});

